	["1 nivel"] = "1 nível",
	["1 no se movió: ya no estaba ahí o el juego no lo soltó."] = "1 não foi movido: já não estava lá ou o jogo não o liberou.",
	["1 objeto"] = "1 item",
	["1 objeto más es de un jefe que aún no descubres."] = "Mais 1 item vem de um chefe que você ainda não descobriu.",
	["1 para después"] = "1 para depois",
