	["Disciplina"] = "Disciplina",
	["Disciplina para subir"] = "Disciplina para subir de nível",
	["Dispara desde lejos: alguien debe ir por él."] = "Ele atira de longe: alguém precisa ir buscá-lo.",
	["Disparas mucho más rápido un rato. Guárdalo para los jefes."] = "Você atira muito mais rápido por um tempo. Guarde para os chefes.",
	["Disparo apuntado: tu disparo más fuerte."] = "Tiro Mirado: seu tiro mais forte.",
	["Disparo arcano: instantáneo, úsalo cuando esté listo."] = "Tiro Arcano: instantâneo, use quando estiver pronto.",
	["Disponible a nivel %d"] = "Disponível no nível %d",
	["Distancia"] = "Distância",
	["Distancia a la que ciudades, torres y cuevas conservan su detalle."] = "Distância em que cidades, torres e cavernas mantêm o detalhe.",
